// ERROR RECORD: turn the Error Trigger payload into an escalations row (status 'system_error')
// and a masked Slack alert. Mode: Run Once for Each Item.
const cfg = $('⚙️ CONFIG').first().json;
const e = $json;
const exec = e.execution || {};
const err = exec.error || e.trigger?.error || {};
const wfName = e.workflow?.name || 'Support workflow';
const now = new Date().toISOString();

const maskEmail = (m) => {
  const [user, domain = ''] = String(m).toLowerCase().split('@');
  const parts = domain.split('.');
  const tld = parts.length > 1 ? parts.pop() : '';
  return `${user.slice(0, 1)}***@${(parts.join('.') || '').slice(0, 1)}***${tld ? `.${tld}` : ''}`;
};
const mask = (s) => String(s || '')
  .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, maskEmail)
  .replace(/\b\d(?:[ -]?\d){12,18}\b/g, '[number removed]')
  .replace(/(x-api-key|authorization|bearer|key=)[^\s,"]*/gi, '$1[redacted]');

const message = mask(err.message || 'Unknown error').slice(0, 1000);
const lastNode = exec.lastNodeExecuted || err.node?.name || 'unknown node';
const reason = `${wfName} failed at "${lastNode}": ${message}`;

const slackText = [
  `:x: *${cfg.COMPANY_NAME || 'Support'} automation error* · [[ESCALATION_ID]]`,
  `*Workflow:* ${wfName}`,
  `*Failed node:* ${lastNode}`,
  `*Error:* ${message}`,
  `*Execution:* ${exec.id ? `${exec.id}${exec.url ? ` · <${exec.url}|open in n8n>` : ''}` : 'n/a'} · *Mode:* ${exec.mode || 'n/a'}`,
  '*Impact:* a chat customer may have seen the widget error message; an email may be unanswered. Check the execution and reply manually.',
  `*Time:* ${now}`,
].join('\n');

return {
  json: {
    ctx: { conversationId: null, channel: null },
    escalation: { reason, slackText },
    turso: {
      purpose: 'escalation_insert',
      timeoutMs: 8000,
      statements: [{
        key: 'escalation',
        // status/priority/reason_code/updated_at come from the admin site's migrations (007).
        sql: `INSERT INTO escalations (conversation_id, channel, claude_confidence, gemini_confidence, reason, gemini_issues, claude_draft,
                status, priority, reason_code, sla_due_at, created_at, updated_at)
              VALUES (?, ?, NULL, NULL, ?, '[]', NULL, 'open', 'high', 'system_error', ?, ?, ?) RETURNING id`,
        args: [exec.id ? `execution:${exec.id}` : null, 'system', reason, new Date(Date.now() + 3600e3).toISOString(), now, now],
      }],
    },
  },
};

// TURSO ENCODE: the ONE place that knows the libSQL / Hrana HTTP format.
// Input:  { ctx, turso: { purpose, timeoutMs, statements: [{ key, sql, args }] }, ... }
// Output: same item + tursoRequest { url, timeoutMs, body } for "🗄️ Turso: Pipeline".
// Docs: https://docs.turso.tech/sdk/http/reference  (POST /v2/pipeline)
// Mode: Run Once for Each Item.
const cfg = $('⚙️ CONFIG').first().json;
const t = $json.turso;

const base = String(cfg.TURSO_DATABASE_URL || '')
  .trim()
  .replace(/^libsql:\/\//i, 'https://')
  .replace(/\/+$/, '');

function toValue(v) {
  if (v === null || v === undefined) return { type: 'null' };
  if (typeof v === 'boolean') return { type: 'integer', value: v ? '1' : '0' };
  if (typeof v === 'number') {
    if (!Number.isFinite(v)) return { type: 'null' };
    return Number.isInteger(v) ? { type: 'integer', value: String(v) } : { type: 'float', value: v };
  }
  if (typeof v === 'object') return { type: 'text', value: JSON.stringify(v) };
  return { type: 'text', value: String(v) };
}

const requests = (t.statements || []).map((s) => ({
  type: 'execute',
  stmt: { sql: s.sql, args: (s.args || []).map(toValue), want_rows: true },
}));
requests.push({ type: 'close' });

return {
  json: {
    ...$json,
    tursoRequest: {
      url: `${base}/v2/pipeline`,
      timeoutMs: Number(t.timeoutMs) || 8000,
      keys: (t.statements || []).map((s, i) => s.key || `stmt_${i}`),
      body: { requests },
    },
  },
};

// TURSO DECODE: turns the Hrana response into plain rows, keyed by statement key.
// Never throws: transport or SQL errors become ok:false with a message.
// Output: { ctx, ...caller fields, turso: { purpose, ok, error, results: { <key>: { ok, rows, error, affected, lastInsertRowid } } } }
// Mode: Run Once for Each Item.
const item = $json;
const req = item.tursoRequest || { keys: [] };
const purpose = item.turso?.purpose;

function fromValue(v) {
  if (!v || v.type === 'null') return null;
  if (v.type === 'integer') { const n = Number(v.value); return Number.isSafeInteger(n) ? n : v.value; }
  if (v.type === 'float') return Number(v.value);
  if (v.type === 'blob') return v.base64;
  return v.value;
}

const results = {};
let ok = true;
let error = null;

if (!Array.isArray(item.results)) {
  ok = false;
  const e = item.error;
  error = typeof e === 'string' ? e : (e?.message || e?.description || JSON.stringify(e || item.message || 'No response from Turso'));
  for (const k of req.keys) results[k] = { ok: false, rows: [], error };
} else {
  req.keys.forEach((key, i) => {
    const r = item.results[i];
    if (!r || r.type !== 'ok') {
      const msg = r?.error?.message || 'Statement failed';
      results[key] = { ok: false, rows: [], error: msg };
      // A missing optional FTS table, or admin-console tables, is not a failure.
      if (key !== 'faq_fts' && !key.startsWith('runtime_')) { ok = false; error = error || `${key}: ${msg}`; }
      return;
    }
    const res = r.response?.result || {};
    const cols = (res.cols || []).map((c, ci) => c.name || `col_${ci}`);
    results[key] = {
      ok: true,
      rows: (res.rows || []).map((row) => Object.fromEntries(row.map((v, ci) => [cols[ci], fromValue(v)]))),
      affected: res.affected_row_count ?? 0,
      lastInsertRowid: res.last_insert_rowid != null ? Number(res.last_insert_rowid) : null,
      error: null,
    };
  });
}

const out = { ...item };
delete out.results; delete out.baton; delete out.base_url; delete out.error; delete out.tursoRequest;
out.turso = { purpose, ok, error, results };
return { json: out };

// SLACK PREPARE: attach the new escalation id to the masked Slack text.
// Input: decoded Turso result of the escalation INSERT ... RETURNING id.
// Mode: Run Once for Each Item.
const j = $json;
const row = j.turso?.results?.escalation?.rows?.[0];
const escalationId = row?.id ?? j.turso?.results?.escalation?.lastInsertRowid ?? null;
const label = escalationId != null ? `#${escalationId}` : '(Turso insert failed: not logged)';
const text = String(j.escalation?.slackText || 'Support escalation').replace('[[ESCALATION_ID]]', label)
  + (j.turso?.ok === false ? `\n:warning: Turso write failed: ${j.turso.error}` : '');
return { json: { ctx: j.ctx, escalationId, slackText: text } };

// SLACK TS WRITE-BACK: store the Slack message timestamp on the escalation row.
// Mode: Run Once for Each Item.
const prep = $('💬 Slack: Prepare Alert').item.json;
const r = $json;
const ts = r.ts || r.message?.ts || r.message_timestamp || null;
if (prep.escalationId == null) {
  return { json: { ctx: prep.ctx, turso: { purpose: 'slack_update', timeoutMs: 8000, statements: [] }, slack: { ts, error: r.error || null } } };
}
return {
  json: {
    ctx: prep.ctx,
    slack: { ts, error: r.error ? (r.error.message || String(r.error)) : null },
    turso: {
      purpose: 'slack_update',
      timeoutMs: 8000,
      statements: [{
        key: 'slack_ts',
        sql: 'UPDATE escalations SET slack_ts = ? WHERE id = ?',
        args: [ts, prep.escalationId],
      }],
    },
  },
};
